#!/usr/bin/env bash
# Public artifact metadata is generated by Fleet, next to the staged server.
# Private/unknown visibility and failed generation never leave a stale receipt.
set -euo pipefail
receipt_repo_root="${1:?repository checkout required}"
receipt_project_root="${2:?project root required}"
receipt_stage_root="${3:?staged server root required}"
receipt_target="$receipt_stage_root/public/.well-known/fleet-release.json"
rm -f "$receipt_target"

if [ "${FLEET_RECEIPT_PUBLIC:-}" != "true" ]; then
  echo "Release receipt omitted: public repository scope is not established."
  exit 0
fi
receipt_producer="${FLEET_RECEIPT_ROOT:-}/scripts/ci/release-receipt.mjs"
if [ ! -f "$receipt_producer" ] || [ -z "${FLEET_RECEIPT_REPO:-}" ]; then
  echo "::warning::Release receipt producer unavailable; deployment has no artifact receipt."
  exit 0
fi
if ! node "$receipt_producer" --public --root "$receipt_repo_root" \
  --dir "$receipt_project_root" --repo "$FLEET_RECEIPT_REPO" --output "$receipt_target"; then
  rm -f "$receipt_target"
  echo "::warning::Release receipt could not be established; package promotion must remain held."
fi
